def out_of_bounds_error(val_str):
    # val_str is original selector string like "10" or "1:10"
    eprint(f"Error: Out of bounds: {val_str}")
    sys.exit(1)

# helpers for bounds resolution
def expand_selector(selector, n, fallback_oob):
    # selector = ('single', val, val, fallback) or ('range', left,right,fallback)
    typ, left, right, fallback = selector
    # Returns list of values (maybe 0,1 or many) or raises OutOfBounds
    # For single:
    if typ == 'single':
        idx = resolve_index(left, n)
        if idx is not None:
            return [idx], fallback
        else:
            # OOB
            if fallback is not None:
                return ['FB:'+fallback], fallback # marker for fallback output
            elif fallback_oob is not None:
                return ['FB:'+fallback_oob], fallback_oob
            else:
                out_of_bounds_error(str(left))
    else: # range
        # Determine indices
        # left/right may be None
        # Resolve left_idx and right_idx with clipping
        # For left None => 0
        # For right None => n-1
        # For left value OOB positive beyond n => OOB
        # For right value positive beyond n => clip to n-1
        # For negative OOB => OOB
        def resolve_left(v):
            if v is None:
                return 0
            if v > 0:
                if v <= n:
                    return v-1
                else:
                    return None  # OOB
            else:
                pos = n + v
                if pos >=0:
                    return pos
                else:
                    return None
        def resolve_right(v):
            if v is None:
                return n-1
            if v > 0:
                if v <= n:
                    return v-1
                else:
                    return n-1  # clip
            else:
                pos = n + v
                if pos >=0:
                    return pos
                else:
                    return None
        l_idx = resolve_left(left)
        r_idx = resolve_right(right)
        if l_idx is None or r_idx is None:
            # OOB for range
            if fallback is not None:
                return ['FB:'+fallback], fallback
            elif fallback_oob is not None:
                return ['FB:'+fallback_oob], fallback_oob
            else:
                # format error string: reconstruct "left:right"
                left_s = "" if left is None else str(left)
                right_s = "" if right is None else str(right)
                out_of_bounds_error(f"{left_s}:{right_s}")
        # If l_idx > r_idx after resolution? Then also? For range like 1:10 on n=2, l_idx=0, r_idx=1 => ok
        # For range 5:10 on n=3, l_idx None => already OOB handled. But if l_idx within and r_idx = n-1, but l_idx > r_idx would happen if left=3,right=2 after resolve? But parser prevents left>right for positive, but for negative may still be?
        if l_idx > r_idx:
