                return ['FB:'+fallback_oob], fallback_oob
            else:
                left_s = "" if left is None else str(left)
                right_s = "" if right is None else str(right)
                out_of_bounds_error(f"{left_s}:{right_s}")
        # produce indices from l_idx to r_idx inclusive
        return list(range(l_idx, r_idx+1)), fallback

